# --- match/fill -> choice (апп-ын тоглуулагч) ---
def _bank(txt):
    return [x.strip() for x in re.split(r"\s{2,}", txt.strip()) if x.strip()]
_m = [x.replace(" ", ". ", 1) for x in _bank(MATCH_BANK)]          # "A. 我还要..."
for it in workbook["reading"]["parts"][1]["items"]:
    it["options"] = list(_m)
_lc = ["A. 练习练习","B. 运动运动","C. 休息休息","D. 问问","E. 找找"]
for it in workbook["reading"]["parts"][3]["items"]:
    it["options"] = list(_lc)
_fd = {1:["用","双","汤","开"],2:["汤","用","双","开"],3:["盘","双","汤","他"],4:["他","用","盘","开"],5:["开","他","汤","双"]}
for it in workbook["reading"]["parts"][2]["items"]:
    it["question_zh"] = it["question_zh"].replace("（　　）", "（"+it["pinyin_hint"]+"）")
    it["options"], _ = shuffle(_fd[it["n"]], it["answer"], f"wbfill{it['n']}")
for pt in workbook["reading"]["parts"][1:]:
    for it in pt["items"]:
        assert it["answer"] in it["options"], it
workbook["reading"]["parts"][2]["instruction_mn"] = "Бичих — хаалтан дахь пиньиньд тохирох ханзыг 4 сонголтоос сонго."
dump("workbook.json", workbook)

